const cfg = $('Params').first().json;
const LING = new Set(cfg.LING);
const who = {};
for (const c of ($('Get Contributors').first().json.contributors || [])) who[String(c.user_id)] = c.email || '';
const live = {};
for (const k of ($('Get Current').first().json.keys || [])) for (const t of (k.translations || [])) live[k.key_id + '|' + t.language_iso] = { k, t };
const F = []; const held = []; const plan = [];
for (const [id, iso, oldT, newT] of cfg.J) {
  const x = live[id + '|' + iso];
  if (!x) { held.push([id, iso, 'not found']); continue; }
  const rb = x.t.reviewed_by != null ? String(x.t.reviewed_by) : '';
  const reviewer = rb ? (who[rb] || ('user ' + rb)) : '';
  const row = { id, iso, reviewed: !!x.t.is_reviewed, reviewer, editor: x.t.modified_by_email || '' };
  plan.push(row);
  if (x.k.is_archived) { held.push([id, iso, 'archived']); continue; }
  if (x.t.translation === newT) { held.push([id, iso, 'already fixed']); continue; }
  if (x.t.translation !== oldT) { held.push([id, iso, 'changed since audit']); continue; }
  if (LING.has(row.editor)) { held.push([id, iso, 'linguist edit']); continue; }
  if (x.t.is_reviewed && rb && rb !== '0' && !who[rb]) { held.push([id, iso, 'reviewer unknown: ' + rb]); continue; }
  if (x.t.is_reviewed && LING.has(who[rb])) { held.push([id, iso, 'reviewed by linguist']); continue; }
  F.push([id, iso, oldT, newT]);
}
if (cfg.mode === 'dry') throw new Error('DRY ' + JSON.stringify({ writable: F.map(f => f[0] + '|' + f[1]), held, plan, contributors: Object.keys(who).length, sample_keys: Object.keys(($('Get Current').first().json.keys || [{}])[0].translations?.[0] || {}) }));
let sendF = cfg.mode === 'one' ? F.slice(0, 1) : F;
const per = {}; const order = [];
for (const [id, iso, o, n] of sendF) { if (!per[id]) { per[id] = []; order.push(id); } per[id].push({ language_iso: iso, translation: n, is_unverified: true }); }
const keys = order.map(id => ({ key_id: Number(id), translations: per[id] }));
if (!keys.length) throw new Error('nothing to write; held ' + JSON.stringify(held));
const out = [];
for (let i = 0; i < keys.length; i += 40) out.push({ json: { body: { keys: keys.slice(i, i + 40) }, n: keys.slice(i, i + 40).reduce((a, k) => a + k.translations.length, 0), held, keys_seen: Object.keys(live).length, planned_total: F.length, F: i === 0 ? sendF : [] } });
return out;

const b = $('Build').all();
const F = b[0].json.F;
const live = {}; for (const k of ($('Read Back').first().json.keys || [])) for (const t of (k.translations||[])) live[k.key_id + '|' + t.language_iso] = t;
let fixed = 0, unver = 0; const notFixed = [];
for (const [id, iso, oldT, newT] of F) { const t = live[id + '|' + iso] || {}; if (t.translation === newT) { fixed++; if (t.is_unverified) unver++; } else notFixed.push([id, iso, String(t.translation).slice(0, 80)]); }
return [{ json: { sent: b.reduce((a, i) => a + i.json.n, 0), planned_total: b[0].json.planned_total, keys_seen: b[0].json.keys_seen, held: b[0].json.held, fixedNow: fixed, unverified: unver, notFixed: notFixed.slice(0, 50), notFixedCount: notFixed.length } }];
